const unitCopies = `-- name: UnitCopies :many
SELECT unit_id, clinic_id, component_kind_code, blood_group_code, rh_positive, phenotype, volume_ml, expires_at, unit_status_code, status_reason, version, updated_at, local_dispatch_obligation_id, clinical_use_blocked FROM unit_copy WHERE unit_id = ANY($1::uuid[])
`

func (q *Queries) UnitCopies(ctx context.Context, unitIds []uuid.UUID) ([]UnitCopy, error) {
	rows, err := q.db.Query(ctx, unitCopies, unitIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []UnitCopy{}
	for rows.Next() {
		var i UnitCopy
		if err := rows.Scan(
			&i.UnitID,
			&i.ClinicID,
			&i.ComponentKindCode,
			&i.BloodGroupCode,
			&i.RhPositive,
			&i.Phenotype,
			&i.VolumeMl,
			&i.ExpiresAt,
			&i.UnitStatusCode,
			&i.StatusReason,
			&i.Version,
			&i.UpdatedAt,
			&i.LocalDispatchObligationID,
			&i.ClinicalUseBlocked,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const unknownClinics = `-- name: UnknownClinics :many
SELECT c::bigint AS clinic_id FROM unnest($1::bigint[]) AS c
WHERE NOT EXISTS (SELECT 1 FROM ref_clinic r WHERE r.clinic_id = c)
`

// Клиники из списка, которых нет в справочнике: проверка источника, получателя и fallback_sources при открытии.
func (q *Queries) UnknownClinics(ctx context.Context, clinicIds []int64) ([]int64, error) {
	rows, err := q.db.Query(ctx, unknownClinics, clinicIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []int64{}
	for rows.Next() {
		var clinic_id int64
		if err := rows.Scan(&clinic_id); err != nil {
			return nil, err
		}
		items = append(items, clinic_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const upsertUnitCopy = `-- name: UpsertUnitCopy :execrows
INSERT INTO unit_copy (unit_id, clinic_id, component_kind_code, blood_group_code, rh_positive, phenotype, volume_ml,
                       expires_at, unit_status_code, status_reason, version, updated_at)
VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9, NULL, $10, $11)
ON CONFLICT (unit_id) DO UPDATE
SET clinic_id = excluded.clinic_id, component_kind_code = excluded.component_kind_code,
    blood_group_code = excluded.blood_group_code, rh_positive = excluded.rh_positive, phenotype = excluded.phenotype,
    volume_ml = excluded.volume_ml, expires_at = excluded.expires_at, unit_status_code = excluded.unit_status_code,
    status_reason = NULL, version = excluded.version, updated_at = excluded.updated_at,
    local_dispatch_obligation_id = CASE WHEN unit_copy.clinic_id<>excluded.clinic_id THEN NULL ELSE unit_copy.local_dispatch_obligation_id END
WHERE unit_copy.version < excluded.version
`

type UpsertUnitCopyParams struct {
	UnitID            uuid.UUID
	ClinicID          int64
	ComponentKindCode string
	BloodGroupCode    string
	RhPositive        bool
	Phenotype         *string
	VolumeMl          int64
	ExpiresAt         time.Time
	UnitStatusCode    string
	Version           int64
	UpdatedAt         time.Time
}

func (q *Queries) UpsertUnitCopy(ctx context.Context, arg UpsertUnitCopyParams) (int64, error) {
	result, err := q.db.Exec(ctx, upsertUnitCopy,
		arg.UnitID,
		arg.ClinicID,
		arg.ComponentKindCode,
		arg.BloodGroupCode,
		arg.RhPositive,
		arg.Phenotype,
		arg.VolumeMl,
		arg.ExpiresAt,
		arg.UnitStatusCode,
		arg.Version,
		arg.UpdatedAt,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

